<script setup lang="ts">
const route=useRoute();const email=ref(''),busy=ref(false),sent=ref(false),error=ref('');
const publicReturn=computed(()=>readerReturn(route.query.returnTo)||'/library');
const returnPath=computed(()=>['/library','/preferences','/radio','/newsroom','/'].includes(String(route.query.returnTo))?String(route.query.returnTo):'/library');
async function requestLink(){if(busy.value)return;busy.value=true;error.value='';try{const preflight=await $fetch<{data:{csrfToken:string}}>('/api/v1/auth/preflight');await $fetch('/api/v1/auth/request',{method:'POST',headers:{'X-CSRF-Token':preflight.data.csrfToken},body:{email:email.value,returnPath:returnPath.value}});rememberReaderReturn(publicReturn.value);sent.value=true;}catch(e){error.value=memberError(e);}finally{busy.value=false;}}
useHead({title:'Sign in — The Aggregator'});
</script>
<template><MemberFrame><p class="eyebrow">Local member edition</p><h1>Sign in or create an account</h1><p>Save stories and keep your listening preferences. Reading, Radio and Newsroom remain available without an account.</p><p class="member-notice">This is a local demonstration. Use a fictional <strong>@example.test</strong> address. Messages go only to the captured mailbox; no external email is delivered.</p><form v-if="!sent" class="member-form" @submit.prevent="requestLink"><label>Email address<input v-model="email" class="field-input" :aria-invalid="!!error||undefined" aria-describedby="signin-hint signin-error" type="email" name="email" autocomplete="email" required maxlength="254" placeholder="reader@example.test"></label><small id="signin-hint" class="field-hint">Use a fictional @example.test address. No password is needed.</small><button class="control control--primary" :disabled="busy" type="submit">{{ busy?'Requesting…':'Send sign-in link' }}</button></form><section v-else class="member-notice" aria-labelledby="check-email-title"><h2 id="check-email-title">Check the captured mailbox</h2><p>If the address is eligible, a short-lived sign-in link has been captured. Open the mailbox from the local demo launcher, then open the link and explicitly confirm.</p><button class="control control--secondary" @click="sent=false">Request another link</button></section><p id="signin-error" class="member-status" role="alert">{{ error }}</p><NuxtLink :to="publicReturn">Cancel and continue</NuxtLink></MemberFrame></template>
